#[test]
fn serde_json_array_push_and_atomic_unproven_calls_reject() { for (src, want) in [("fn f() error {\n    arr := serde_json.new_array()?\n    v := arr.array(\"users\")?\n    arr.push_string(\"x\")?\n    _ = v\n    return nil\n}\n", "HYB-E3101"), ("fn f() error {\n    arr := serde_json.new_array()?\n    v := arr.array(\"users\")?\n    serde_json.push_string(arr, \"x\")?\n    _ = v\n    return nil\n}\n", "HYB-E3101"), ("fn w(x any) { _ = x }\nfn f() {\n    v := atomic.value()\n    task w(v)\n}\n", "HYB-E3005")] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", src).unwrap()); assert!(r.diagnostics.iter().any(|d| d.code == want), "{src}: {:?}", r.diagnostics); } assert!(hy_check::check_file(&hy_syntax::parse_file("t.hy", "fn f() error {\n    arr := serde_json.new_array()?\n    arr.push_string(\"x\")?\n    return nil\n}\n").unwrap()).diagnostics.is_empty()); }
